import { PluginFactory } from "pocketpages";

//#region src/index.d.ts
type OAuth2ProviderInfo = {
  name: string;
  state: string;
  codeChallenge: string;
  codeVerifier: string;
  redirectUrl: string;
};
type User = {
  avatar: string;
  collectionId: string;
  collectionName: string;
  created: string;
  emailVisibility: boolean;
  email: string;
  id: string;
  name: string;
  updated: string;
  username: string;
  verified: boolean;
};
type AuthData = {
  token: string;
  record: User;
};
type AuthOptions = {
  collection: string;
};
type OAuth2RequestOptions = {
  cookieName: string;
  redirectPath: string;
  autoRedirect: boolean;
} & AuthOptions;
type OAuth2SignInOptions = {
  cookieName: string;
} & AuthOptions;
type CreateUserOptions = {
  sendVerificationEmail: boolean;
} & AuthOptions;
declare const authPluginFactory: PluginFactory;
//#endregion
export { AuthData, AuthOptions, CreateUserOptions, OAuth2ProviderInfo, OAuth2RequestOptions, OAuth2SignInOptions, User, authPluginFactory as default };